const IP_IGNORE_BITS1 = 1n;
export const isGoogleIp = myip => {
  const obj = parseIp(myip);

  if (obj.version == 4) {
    let ip = obj.number >> IP_IGNORE_BITS1;
    return googleIpRange.some(prefix => {
      if (prefix["ipv4Prefix"]) {
	const v4prefix = prefix["ipv4Prefix"];

	const [network, len] = v4prefix.split("/");
	const networkObj = parseIp(network);

	let pref = BigInt(32 - len);
	let msk1 = ((1n << pref) - 1n) >> IP_IGNORE_BITS1;
	let net0 = networkObj.number >> IP_IGNORE_BITS1;

	if ((ip & ~msk1) == net0) return true;
      }
    });
  }

  if (obj.version == 6) {
    let ip = obj.number >> (64n + IP6_IGNORE_BITS);

    return googleIpRange.some(prefix => {
      if (prefix["ipv6Prefix"]) {
	const v6prefix = prefix["ipv6Prefix"];
	const [network, len] = v6prefix.split("/");
	const networkObj = parseIp(network);

	let pref = BigInt(48 - len);
	let msk1 = ((1n << pref) - 1n);
	let net0 = networkObj.number >> (64n + IP6_IGNORE_BITS);

	if ((ip & ~msk1) == net0) return true;
      }
    });
  }

  return false;
}

